mapper.select:
SELECT id, org_id, account_id, role, status, joined_at
FROM organization_member
WHERE org_id = #{orgId}
  AND account_id = #{accountId}
  AND status = 'ACTIVE'
LIMIT 1

SELECT id, org_id, account_id, role, status, joined_at, updated_at
FROM organization_member
WHERE org_id = #{orgId}
  AND account_id = #{accountId}
ORDER BY id DESC
LIMIT 1

SELECT id, org_id, account_id, role, status, joined_at
FROM organization_member
WHERE id = #{id}

mapper.update:
UPDATE organization_member
SET status = #{status}
WHERE id = #{id}
  AND status = 'ACTIVE'

UPDATE organization_member
SET role = #{role}
WHERE id = #{id}
  AND status = 'ACTIVE'

mapper.select:
SELECT m.id AS memberId, m.account_id AS accountId, a.username AS username, m.role AS role, m.joined_at AS joinedAt FROM organization_member m JOIN account a ON a.id = m.account_id WHERE m.org_id = #{orgId} AND m.status = 'ACTIVE'
AND a.username LIKE CONCAT('%', #{query}, '%')
ORDER BY m.joined_at ASC, m.id ASC LIMIT #{limit} OFFSET #{offset}
